<script setup lang="ts">
// Vue adaptation of a9fe401 SelectionActionMenu/MarkdownSelectionTooltip.
import{ref,watch,onMounted,onBeforeUnmount,nextTick}from'vue';
const props=defineProps<{scope?:HTMLElement;enabled:boolean}>(),emit=defineEmits<{(e:'quote',text:string):void;(e:'new-task',text:string):void}>();
const text=ref(''),menu=ref<HTMLElement>(),position=ref({left:'12px',top:'12px'});let timer:ReturnType<typeof setTimeout>|undefined;
async function capture(){if(!props.enabled){text.value='';return;}const selection=window.getSelection();if(!selection?.rangeCount||selection.isCollapsed){text.value='';return;}const range=selection.getRangeAt(0);if(!props.scope?.contains(range.commonAncestorContainer)){text.value='';return;}const value=selection.toString().trim();if(!value){text.value='';return;}const box=range.getBoundingClientRect();text.value=value;await nextTick();const m=menu.value?.getBoundingClientRect();if(!m)return;position.value={left:`${Math.max(12,Math.min(innerWidth-m.width-12,(box.left+box.right-m.width)/2))}px`,top:`${Math.max(12,Math.min(innerHeight-m.height-12,box.top-m.height-8>=12?box.top-m.height-8:box.bottom+8))}px`};}
function schedule(){clearTimeout(timer);timer=setTimeout(capture,0);}function hide(){text.value='';}function action(kind:'quote'|'new-task'){if(text.value.length>8000)return;if(kind==='quote')emit('quote',text.value);else emit('new-task',text.value);hide();window.getSelection()?.removeAllRanges();}
function key(e:KeyboardEvent){if(e.key==='Escape')hide();}
watch(()=>props.enabled,hide);onMounted(()=>{document.addEventListener('selectionchange',schedule);window.addEventListener('scroll',hide,true);window.addEventListener('keydown',key);});onBeforeUnmount(()=>{clearTimeout(timer);document.removeEventListener('selectionchange',schedule);window.removeEventListener('scroll',hide,true);window.removeEventListener('keydown',key);});
</script>
<template><Teleport to="body"><div v-if="text" ref="menu" class="selection-menu" :style="position" role="toolbar" aria-label="选中文字操作" @pointerdown.prevent @mousedown.prevent><span v-if="text.length>8000">单次最多引用8000字符</span><template v-else><button @click="action('quote')">添加到当前任务</button><i></i><button @click="action('new-task')">在新任务中提问</button></template></div></Teleport></template>
<style scoped>.selection-menu{position:fixed;z-index:1100;display:flex;width:max-content;max-width:calc(100vw - 24px);overflow:hidden;border:1px solid var(--color-popover-border);border-radius:8px;background:var(--color-menu);color:var(--fg);font-size:var(--text-ui-sm);box-shadow:0 4px 12px #0002}.selection-menu button,.selection-menu>span{padding:6px 10px;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}.selection-menu button:hover{background:var(--color-menu-hover)}.selection-menu i{width:1px;background:var(--border)}</style>
